function safeStorageGet(key, fallback) {
    try {
        const raw = localStorage.getItem(key);
        return raw ? JSON.parse(raw) : fallback;
    } catch (e) {
        return fallback;
    }
}

function safeStorageSet(key, val) {
    try {
        localStorage.setItem(key, JSON.stringify(val));
    } catch (e) {}
}

function safeStorageRemove(key) {
    try {
        localStorage.removeItem(key);
    } catch (e) {}
}

function formatINR(amount) {
    return '₹' + Math.round(Number(amount || 0)).toLocaleString('en-IN');
}

function showLuxuryToast(message) {
    const container = document.getElementById('luxuryToastContainer');
    if (!container) return;
    const toast = document.createElement('div');
    toast.className = 'luxury-toast';
    toast.innerHTML = `<span class="pro-icon-badge" style="width:22px;height:22px;">✓</span><span>${message}</span>`;
    container.appendChild(toast);
    setTimeout(() => {
        toast.style.opacity = '0';
        toast.style.transform = 'translateX(20px)';
        toast.style.transition = 'all 0.25s ease';
        setTimeout(() => toast.remove(), 260);
    }, 3400);
}
const showToast = showLuxuryToast;

function getTotalGarmentUnits(product) {
    if (!product || !product.sizes) return 0;
    return Object.values(product.sizes).reduce((sum, q) => sum + Math.max(0, Number(q || 0)), 0);
}

function isGarmentInStock(product) {
    return Boolean(product && product.inStock !== false && getTotalGarmentUnits(product) > 0);
}

