function openAdminStudioModal() {
    const modal = document.getElementById('adminStudioModal');
    if (!modal) return;
    modal.style.display = 'flex';
    refreshAdminStudio();
    updateAdminLiveHangerPreview();
}
const openAdminPortalModal = openAdminStudioModal;

function closeAdminStudioModal() {
    const modal = document.getElementById('adminStudioModal');
    if (modal) modal.style.display = 'none';
}
const closeAdminPortalModal = closeAdminStudioModal;

function switchAdminStudioTab(tabKey) {
    const map = {
        INVENTORY: { panel: 'adminTabInventory', btn: 'adminTabBtnInventory' },
        ADD_PRODUCT: { panel: 'adminTabAddProduct', btn: 'adminTabBtnAddProduct' },
        ORDERS: { panel: 'adminTabOrders', btn: 'adminTabBtnOrders' },
        CUSTOMERS: { panel: 'adminTabCustomers', btn: 'adminTabBtnCustomers' },
        DATABASE: { panel: 'adminTabDatabase', btn: 'adminTabBtnDatabase' }
    };
    Object.entries(map).forEach(([k, cfg]) => {
        const p = document.getElementById(cfg.panel);
        const b = document.getElementById(cfg.btn);
        if (p) p.style.display = k === tabKey ? 'block' : 'none';
        if (b) b.classList.toggle('active', k === tabKey);
    });
    if (tabKey === 'ADD_PRODUCT') {
        updateAdminLiveHangerPreview();
    } else if (tabKey === 'DATABASE') {
        refreshDatabaseManagerPanel();
    }
}

function refreshAdminStudio() {
    renderAdminKpiMetrics();
    renderAdminInventoryCards();
    renderAdminOrdersPipeline();
    renderAdminCustomersDirectory();
    refreshDatabaseManagerPanel();
}

function renderAdminKpiMetrics() {
    let totalUnits = 0;
    let outCount = 0;
    showroomCatalog.forEach(p => {
        const u = getTotalGarmentUnits(p);
        if (isGarmentInStock(p)) {
            totalUnits += u;
        } else {
            outCount++;
        }
    });
    const rev = savedShowroomOrders.reduce((s, o) => s + Number(o.grandTotal || 0), 0) || 48950;

    const elStyles = document.getElementById('adminKpiTotalStyles');
    const elUnits = document.getElementById('adminKpiInStockUnits');
    const elOut = document.getElementById('adminKpiOutStockCount');
    const elRev = document.getElementById('adminKpiTotalRevenue');

    if (elStyles) elStyles.textContent = `${showroomCatalog.length} Collections`;
    if (elUnits) elUnits.textContent = `${totalUnits.toLocaleString('en-IN')} Units`;
    if (elOut) elOut.textContent = `${outCount} Stock-Out`;
    if (elRev) elRev.textContent = formatINR(rev);
}

function filterAdminInventory(filterType) {
    currentAdminInventoryFilter = filterType || 'ALL';
    switchAdminStudioTab('INVENTORY');
    document.querySelectorAll('#adminInventoryFilterPills .studio-seg-pill').forEach(btn => {
        btn.classList.toggle('active', btn.getAttribute('data-filter') === currentAdminInventoryFilter);
    });
    renderAdminInventoryCards();
}

function renderAdminInventoryCards() {
    const grid = document.getElementById('adminInventoryCardsGrid');
    if (!grid) return;

    const q = (document.getElementById('adminInventorySearchInput')?.value || '').trim().toLowerCase();

    const list = showroomCatalog.filter(item => {
        const inStock = isGarmentInStock(item);
        if (currentAdminInventoryFilter === 'IN_STOCK' && !inStock) return false;
        if (currentAdminInventoryFilter === 'STOCK_OUT' && inStock) return false;
        if (['EETHMAN', 'HOLSTEINER', 'LOUIS_VENTO', 'KIDS_WOMENS'].includes(currentAdminInventoryFilter)) {
            if (!matchesDepartmentFilter(item, currentAdminInventoryFilter)) return false;
        }
        if (q) {
            const hay = `${item.title} ${item.brand} ${item.sku} ${item.fabric} ${item.department}`.toLowerCase();
            return hay.includes(q);
        }
        return true;
    });

    if (!list.length) {
        grid.innerHTML = `<div style="grid-column:1/-1;padding:32px;text-align:center;color:#94A3B8;border:1px dashed rgba(212,175,55,0.35);border-radius:16px;">No collections match this filter.</div>`;
        return;
    }

    grid.innerHTML = list.map(item => {
        const inStock = isGarmentInStock(item);
        const totalUnits = getTotalGarmentUnits(item);
        const disc = item.mrp > item.price ? Math.round(((item.mrp - item.price) / item.mrp) * 100) : 0;

        const sizePods = Object.entries(item.sizes || {}).map(([sz, qty]) => {
            const low = !inStock || Number(qty) < 5;
            return `
                <div class="studio-size-pod ${low ? 'low-stock' : ''}">
                    <div class="size-pod-header">
                        <span class="size-pod-label">${sz}</span>
                        <span class="size-pod-status-dot ${low ? 'low' : 'ok'}"></span>
                    </div>
                    <span class="size-pod-qty">${inStock ? qty : 0} pcs</span>
                    <div class="size-pod-Step-btns">
                        <button type="button" class="size-step-btn" onclick="adjustVariantSizeStock('${item.id}', '${sz}', -5)">-5</button>
                        <button type="button" class="size-step-btn plus" onclick="adjustVariantSizeStock('${item.id}', '${sz}', 10)">+10</button>
                    </div>
                </div>
            `;
        }).join('');

        return `
            <div class="studio-garment-card">
                <div class="studio-card-top">
                    <div class="studio-card-thumb-pair" onclick="closeAdminStudioModal(); handleGarmentHangerClick('${item.id}');" title="Preview in 3D Spotlight">
                        <img src="${item.frontImg}" alt="${item.title}" />
                        <span class="studio-thumb-3d-badge">3D STAGE</span>
                    </div>
                    <div class="studio-card-meta">
                        <div class="studio-meta-badges">
                            <span class="studio-seg-badge">${item.brand} • ${item.sku || item.department}</span>
                            <span class="studio-disc-badge">${disc}% OFF</span>
                        </div>
                        <h4 class="studio-card-title">${item.title}</h4>
                        <div class="studio-card-fabric">${item.fabric}</div>
                        <div style="font-size:11.5px;color:${inStock ? '#6EE7B7' : '#FCA5A5'};font-weight:800;">
                            ${inStock ? `✓ IN STOCK (${totalUnits} Units)` : '✕ STOCK OUT (Paused on Storefront)'}
                        </div>
                    </div>
                </div>

                <div class="whole-garment-stock-bar">
                    <button type="button" class="stock-state-btn in-stock-btn ${inStock ? 'active' : ''}" onclick="setWholeGarmentStockState('${item.id}', true)">
                        ✓ Mark IN STOCK
                    </button>
                    <button type="button" class="stock-state-btn stock-out-btn ${!inStock ? 'active' : ''}" onclick="setWholeGarmentStockState('${item.id}', false)">
                        ✕ Mark STOCK OUT
                    </button>
                    <button type="button" class="db-delete-record-btn" onclick="deleteProductFromDatabase('${item.id}')" title="Delete this garment collection from the database">
                        Delete DB
                    </button>
                </div>

                <div class="studio-price-control-bar">
                    <div class="studio-price-field">
                        <label>Selling Price (₹)</label>
                        <input type="number" id="adminPrice_${item.id}" value="${item.price}" min="99" />
                    </div>
                    <div class="studio-price-field">
                        <label>MRP (₹)</label>
                        <input type="number" id="adminMrp_${item.id}" value="${item.mrp}" min="99" />
                    </div>
                    <button type="button" class="studio-price-save-btn" onclick="updateAdminProductPrice('${item.id}')">
                        Save to DB
                    </button>
                </div>

                <div class="studio-size-matrix">
                    ${sizePods}
                </div>
            </div>
        `;
    }).join('');
}

function setWholeGarmentStockState(productId, makeInStock) {
    const prod = showroomCatalog.find(p => p.id === productId);
    if (!prod) return;
    prod.inStock = Boolean(makeInStock);
    if (makeInStock && getTotalGarmentUnits(prod) === 0) {
        prod.sizes = { M: 20, L: 25, XL: 20, XXL: 15 };
    }
    safeStorageSet(STORAGE_KEYS.CATALOG, showroomCatalog);
    applyCatalogFilters();
    refreshAdminStudio();
    showLuxuryToast(`${prod.title} saved as ${makeInStock ? 'IN STOCK' : 'STOCK OUT'} in Database!`);
}

function deleteProductFromDatabase(productId) {
    const idx = showroomCatalog.findIndex(p => p.id === productId);
    if (idx === -1) return;
    const removedTitle = showroomCatalog[idx].title;
    showroomCatalog.splice(idx, 1);
    safeStorageSet(STORAGE_KEYS.CATALOG, showroomCatalog);
    applyCatalogFilters();
    refreshAdminStudio();
    showLuxuryToast(`Deleted "${removedTitle}" from Showroom Database.`);
}

function adjustVariantSizeStock(productId, sizeLabel, delta) {
    const prod = showroomCatalog.find(p => p.id === productId);
    if (!prod || !prod.sizes) return;
    const nextQty = Math.max(0, Number(prod.sizes[sizeLabel] || 0) + delta);
    prod.sizes[sizeLabel] = nextQty;
    prod.inStock = getTotalGarmentUnits(prod) > 0;

    safeStorageSet(STORAGE_KEYS.CATALOG, showroomCatalog);
    applyCatalogFilters();
    refreshAdminStudio();
    showLuxuryToast(`Database updated: ${prod.title} (${sizeLabel}) = ${nextQty} pcs.`);
}

function updateAdminProductPrice(productId) {
    const prod = showroomCatalog.find(p => p.id === productId);
    if (!prod) return;
    const newPrice = Number(document.getElementById(`adminPrice_${productId}`)?.value || prod.price);
    const newMrp = Number(document.getElementById(`adminMrp_${productId}`)?.value || prod.mrp);
    prod.price = Math.max(99, newPrice);
    prod.mrp = Math.max(prod.price, newMrp);

    safeStorageSet(STORAGE_KEYS.CATALOG, showroomCatalog);
    applyCatalogFilters();
    refreshAdminStudio();
    showLuxuryToast(`Database price updated for ${prod.title}: ${formatINR(prod.price)} (MRP ${formatINR(prod.mrp)}).`);
}

function fillAdminSampleTemplate(templateKey) {
    const tpl = ADMIN_SAMPLE_TEMPLATES[templateKey];
    if (!tpl) return;
    document.getElementById('adminNewBrand').value = tpl.brand;
    document.getElementById('adminNewTitle').value = tpl.title;
    document.getElementById('adminNewDepartment').value = tpl.department;
    document.getElementById('adminNewFabric').value = tpl.fabric;
    document.getElementById('adminNewPrice').value = tpl.price;
    document.getElementById('adminNewMrp').value = tpl.mrp;
    document.getElementById('adminNewStock').value = tpl.stock;
    document.getElementById('adminNewSku').value = tpl.sku;
    document.getElementById('adminNewFrontImg').value = '';
    document.getElementById('adminNewBackImg').value = '';
    document.getElementById('adminNewDesc').value = tpl.desc;
    updateAdminLiveHangerPreview(tpl.frontImg, tpl.backImg);
    showLuxuryToast(`Loaded "${tpl.title}" into Live 3D Hanger Preview!`);
}

function toggleAdminPreviewFlip() {
    isAdminPreviewFlipped = !isAdminPreviewFlipped;
    updateAdminLiveHangerPreview();
}

function updateAdminLiveHangerPreview(customFront, customBack) {
    const brand = (document.getElementById('adminNewBrand')?.value || 'EETHMAN').trim();
    const title = (document.getElementById('adminNewTitle')?.value || 'EETHMAN Sky-Blue Pinstripe Slim-Fit Shirt').trim();
    const dept = document.getElementById('adminNewDepartment')?.value || 'EETHMAN';
    const fabric = (document.getElementById('adminNewFabric')?.value || '100% Combed Linen-Cotton').trim();
    const price = Number(document.getElementById('adminNewPrice')?.value || 999);
    const mrp = Number(document.getElementById('adminNewMrp')?.value || 1499);
    const frontInput = (document.getElementById('adminNewFrontImg')?.value || '').trim();
    const backInput = (document.getElementById('adminNewBackImg')?.value || '').trim();

    const defaultMap = {
        EETHMAN: [CLIENT_PDF_ASSETS.eethman_sky_lav, CLIENT_PDF_ASSETS.eethman_detail],
        HOLSTEINER: [CLIENT_PDF_ASSETS.holsteiner_black, CLIENT_PDF_ASSETS.holsteiner_trio],
        LOUIS_VENTO: [CLIENT_PDF_ASSETS.lv_cream_check, CLIENT_PDF_ASSETS.lv_white_check_full],
        KIDS_WOMENS: [CLIENT_PDF_ASSETS.kids_festive_front, CLIENT_PDF_ASSETS.womens_festive_front]
    };
    const pair = defaultMap[dept] || defaultMap.EETHMAN;
    const defaultFront = customFront || pair[0];
    const defaultBack = customBack || pair[1];

    const imgUrl = isAdminPreviewFlipped ? (backInput || frontInput || defaultBack) : (frontInput || defaultFront);
    const disc = mrp > price ? Math.round(((mrp - price) / mrp) * 100) : 15;

    const imgEl = document.getElementById('adminLivePreviewImg');
    if (imgEl) imgEl.src = imgUrl;

    document.getElementById('adminLivePreviewDept').textContent = dept;
    document.getElementById('adminLivePreviewDiscount').textContent = `${disc}% OFF`;
    document.getElementById('adminLivePreviewSide').textContent = isAdminPreviewFlipped ? 'DETAIL 180° VIEW' : 'FRONT VIEW';
    document.getElementById('adminLivePreviewFabric').textContent = `${brand} • ${fabric}`;
    document.getElementById('adminLivePreviewTitle').textContent = title;
    document.getElementById('adminLivePreviewPrice').textContent = formatINR(price);
    document.getElementById('adminLivePreviewMrp').textContent = formatINR(mrp);
}

function handleCreateNewCollection(e) {
    e.preventDefault();
    const brand = (document.getElementById('adminNewBrand')?.value || 'EETHMAN').trim();
    const title = (document.getElementById('adminNewTitle')?.value || 'New Showroom Collection').trim();
    const department = document.getElementById('adminNewDepartment')?.value || 'EETHMAN';
    const fabric = (document.getElementById('adminNewFabric')?.value || '100% Combed Cotton').trim();
    const price = Number(document.getElementById('adminNewPrice')?.value || 1099);
    const mrp = Number(document.getElementById('adminNewMrp')?.value || 1599);
    const initStock = Math.max(0, Number(document.getElementById('adminNewStock')?.value || 25));
    const sku = (document.getElementById('adminNewSku')?.value || ('KMF-' + Date.now().toString().slice(-4))).trim();
    const frontInput = (document.getElementById('adminNewFrontImg')?.value || '').trim();
    const backInput = (document.getElementById('adminNewBackImg')?.value || '').trim();
    const desc = (document.getElementById('adminNewDesc')?.value || `${fabric} — available at Kiruthis Mens Fashions, Tirupur.`).trim();

    const defaultMap = {
        EETHMAN: [CLIENT_PDF_ASSETS.eethman_sky_lav, CLIENT_PDF_ASSETS.eethman_detail],
        HOLSTEINER: [CLIENT_PDF_ASSETS.holsteiner_black, CLIENT_PDF_ASSETS.holsteiner_trio],
        LOUIS_VENTO: [CLIENT_PDF_ASSETS.lv_cream_check, CLIENT_PDF_ASSETS.lv_white_check_full],
        KIDS_WOMENS: [CLIENT_PDF_ASSETS.kids_festive_front, CLIENT_PDF_ASSETS.womens_festive_front]
    };
    const pair = defaultMap[department] || defaultMap.EETHMAN;

    const newItem = {
        id: 'KMF-' + (showroomCatalog.length + 101 + Math.floor(Math.random() * 90)),
        sku,
        brand,
        title,
        department,
        price,
        mrp,
        fabric,
        gsm: 'Made in India',
        fit: 'Slim / Tailored Fit',
        inStock: initStock > 0,
        frontImg: frontInput || pair[0],
        backImg: backInput || frontInput || pair[1],
        description: desc,
        sizes: { M: initStock, L: initStock, XL: initStock, XXL: initStock }
    };

    showroomCatalog.unshift(newItem);
    safeStorageSet(STORAGE_KEYS.CATALOG, showroomCatalog);
    applyCatalogFilters();
    refreshAdminStudio();
    switchAdminStudioTab('INVENTORY');
    showLuxuryToast(`Saved "${title}" to Database & hung on Live 3D Rail!`);
}

function renderAdminOrdersPipeline() {
    const box = document.getElementById('adminOrdersPipelineList');
    if (!box) return;

    const stages = [
        { code: 'CONFIRMED', label: '1. Confirmed' },
        { code: 'PACKED', label: '2. Packed' },
        { code: 'SHIPPED', label: '3. Shipped' },
        { code: 'OUT_FOR_DELIVERY', label: '4. Out for Delivery' },
        { code: 'DELIVERED', label: '5. Delivered' }
    ];

    box.innerHTML = savedShowroomOrders.map((ord, idx) => {
        const curIdx = Math.max(0, stages.findIndex(s => s.code === (ord.status || 'CONFIRMED')));
        const summary = (ord.items || []).map(i => `${i.title} (${i.size} × ${i.qty})`).join(', ');
        const stepsHtml = stages.map((st, sIdx) => `
            <button type="button"
                    class="pipeline-step-btn ${sIdx < curIdx ? 'completed' : (sIdx === curIdx ? 'current' : '')}"
                    onclick="updateAdminOrderStage(${idx}, '${st.code}')">
                ${st.label}
            </button>
        `).join('');

        return `
            <div class="studio-order-card">
                <div class="studio-order-top">
                    <div class="studio-order-id-group">
                        <span class="studio-order-id-badge">${ord.orderNumber}</span>
                        <div>
                            <strong style="color:#F8FAFC;font-size:13.5px;">${ord.customerName}</strong>
                            <span style="color:#6EE7B7;font-size:12px;margin-left:8px;">+91 ${ord.customerPhone}</span>
                            <span style="color:#94A3B8;font-size:11.5px;margin-left:8px;">• ${ord.invoiceDate}</span>
                        </div>
                    </div>
                    <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
                        <strong style="color:#FDE68A;font-size:16px;">${formatINR(ord.grandTotal)}</strong>
                        <button type="button" class="gold-outline-btn" onclick="openSavedInvoiceModal(${idx})">
                            View / Print GST Invoice
                        </button>
                        <button type="button" class="db-delete-record-btn" onclick="deleteOrderFromDatabase(${idx})">
                            Delete
                        </button>
                    </div>
                </div>
                <div style="font-size:12px;color:#CBD5E1;">
                    <b style="color:#FDE68A;">Items:</b> ${summary}
                    ${ord.freeGift ? ` | <b style="color:#6EE7B7;">🎁 ${ord.freeGift}</b>` : ''}
                </div>
                <div class="studio-pipeline-track">${stepsHtml}</div>
            </div>
        `;
    }).join('');
}

function updateAdminOrderStage(orderIdx, stageCode) {
    if (!savedShowroomOrders[orderIdx]) return;
    savedShowroomOrders[orderIdx].status = stageCode;
    safeStorageSet(STORAGE_KEYS.ORDERS, savedShowroomOrders);
    renderAdminOrdersPipeline();
    showLuxuryToast(`Database updated: Order ${savedShowroomOrders[orderIdx].orderNumber} -> ${stageCode}`);
}

function deleteOrderFromDatabase(orderIdx) {
    if (!savedShowroomOrders[orderIdx]) return;
    const ordNo = savedShowroomOrders[orderIdx].orderNumber;
    savedShowroomOrders.splice(orderIdx, 1);
    safeStorageSet(STORAGE_KEYS.ORDERS, savedShowroomOrders);
    refreshAdminStudio();
    renderPersonalBagDrawer();
    showLuxuryToast(`Deleted Order ${ordNo} from Database.`);
}

function createDemoShowroomOrder() {
    const num = Math.floor(10000 + Math.random() * 90000);
    const sample1 = showroomCatalog[0] || DEFAULT_SHOWROOM_CATALOG[0];
    const sample2 = showroomCatalog[4] || DEFAULT_SHOWROOM_CATALOG[4];
    const total = Number(sample1.price || 999) + Number(sample2.price || 1299);
    savedShowroomOrders.unshift({
        orderNumber: `KMF-2026-${num}`,
        invoiceDate: new Date().toLocaleString('en-IN'),
        customerName: 'Prakash Senthil (Tirupur)',
        customerPhone: '9894011223',
        customerEmail: 'prakash.tirupur@gmail.com',
        shippingAddress: '42 Kumaran Road, Tirupur - 641 601 (Tamil Nadu)',
        paymentMode: 'ONLINE_PREPAID',
        transactionRef: 'UPI_QR_' + num,
        freeGift: total >= 2000 ? 'FREE Branded Round-Neck T-Shirt (Size L)' : null,
        status: 'CONFIRMED',
        grandTotal: total,
        items: [
            { title: sample1.title, size: 'L', qty: 1, price: sample1.price },
            { title: sample2.title, size: 'L', qty: 1, price: sample2.price }
        ]
    });
    safeStorageSet(STORAGE_KEYS.ORDERS, savedShowroomOrders);
    refreshAdminStudio();
    renderPersonalBagDrawer();
    showLuxuryToast(`Created new customer order KMF-2026-${num} in Database!`);
}

function renderAdminCustomersDirectory() {
    const grid = document.getElementById('adminCustomersGrid');
    if (!grid) return;
    const q = (document.getElementById('adminCustomerSearchInput')?.value || '').trim().toLowerCase();

    const list = registeredUsers.filter(u => {
        if (!q) return true;
        return `${u.fullName} ${u.phone} ${u.email}`.toLowerCase().includes(q);
    });

    grid.innerHTML = list.map(u => {
        const initials = (u.fullName || 'KM').split(' ').map(w => w[0]).join('').slice(0, 2).toUpperCase();
        const isAdmin = u.role === 'ADMIN';
        return `
            <div class="studio-customer-card">
                <div class="customer-monogram-avatar">${initials}</div>
                <div style="flex:1;min-width:0;">
                    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:3px;">
                        <strong style="font-size:13.5px;color:#F8FAFC;">${u.fullName}</strong>
                        <span class="studio-seg-badge">${isAdmin ? 'ADMIN' : 'VIP CUSTOMER'}</span>
                    </div>
                    <div style="font-size:12px;color:#94A3B8;margin-bottom:8px;">+91 ${u.phone} • ${u.email}</div>
                    <div style="display:flex;gap:6px;flex-wrap:wrap;">
                        <a href="tel:+91${u.phone}" class="admin-mini-btn" style="text-decoration:none;">Call</a>
                        <a href="https://wa.me/91${u.phone}" target="_blank" rel="noopener noreferrer" class="admin-mini-btn emerald" style="text-decoration:none;">WhatsApp</a>
                        <button type="button" class="admin-mini-btn" onclick="toggleCustomerAdminAccess('${u.userId}')">
                            ${isAdmin ? 'Set Customer' : 'Grant Admin'}
                        </button>
                        <button type="button" class="db-delete-record-btn" style="padding:4px 8px;font-size:10.5px;" onclick="deleteCustomerFromDatabase('${u.userId}')">
                            Delete
                        </button>
                    </div>
                </div>
            </div>
        `;
    }).join('');
}

function toggleCustomerAdminAccess(userId) {
    const u = registeredUsers.find(item => item.userId === userId);
    if (!u) return;
    u.role = u.role === 'ADMIN' ? 'CUSTOMER' : 'ADMIN';
    safeStorageSet(STORAGE_KEYS.USERS, registeredUsers);
    renderAdminCustomersDirectory();
    showLuxuryToast(`Database updated: ${u.fullName} role set to ${u.role}`);
}

function deleteCustomerFromDatabase(userId) {
    const idx = registeredUsers.findIndex(u => u.userId === userId);
    if (idx === -1) return;
    const name = registeredUsers[idx].fullName;
    registeredUsers.splice(idx, 1);
    safeStorageSet(STORAGE_KEYS.USERS, registeredUsers);
    refreshAdminStudio();
    showLuxuryToast(`Deleted customer "${name}" from Database.`);
}

function addNewCustomerFromAdmin() {
    const nameEl = document.getElementById('adminNewCustName');
    const phoneEl = document.getElementById('adminNewCustPhone');
    const fullName = (nameEl?.value || '').trim();
    const phone = (phoneEl?.value || '').replace(/\D/g, '').slice(-10);

    if (!fullName || phone.length !== 10) {
        showLuxuryToast('Enter Full Name and 10-Digit Mobile Number.');
        return;
    }
    registeredUsers.unshift({
        userId: 'CUST-' + Date.now(),
        fullName,
        phone,
        email: `${fullName.toLowerCase().replace(/[^a-z0-9]/g, '')}@kiruthis.in`,
        role: 'CUSTOMER'
    });
    safeStorageSet(STORAGE_KEYS.USERS, registeredUsers);
    if (nameEl) nameEl.value = '';
    if (phoneEl) phoneEl.value = '';
    refreshAdminStudio();
    showLuxuryToast(`Added ${fullName} to Showroom Customer Database!`);
}

// ============================================================================
// 10B. TAB 5: FINE-TUNED VISUAL SPREADSHEET & JSON DATABASE MANAGER
// ============================================================================
function selectDatabaseManagerTable(tableKey) {
    const selEl = document.getElementById('dbTableSelector');
    if (selEl) selEl.value = tableKey;
    document.querySelectorAll('#dbSubtablePills .db-subtable-pill').forEach(btn => {
        btn.classList.toggle('active', btn.getAttribute('data-dbtable') === tableKey);
    });
    loadSelectedDatabaseTableIntoEditor();
}

function refreshDatabaseManagerPanel() {
    const catCount = document.getElementById('dbStatCatalogCount');
    const varCount = document.getElementById('dbStatVariantsCount');
    const ordCount = document.getElementById('dbStatOrdersCount');
    const usrCount = document.getElementById('dbStatUsersCount');

    if (catCount) catCount.textContent = `${showroomCatalog.length} Collections`;
    if (varCount) varCount.textContent = `${showroomCatalog.length * 4} Size SKUs`;
    if (ordCount) ordCount.textContent = `${savedShowroomOrders.length} Invoices`;
    if (usrCount) usrCount.textContent = `${registeredUsers.length} Accounts`;

    loadSelectedDatabaseTableIntoEditor();
}

function renderVisualDatabaseSpreadsheet(tableKey) {
    const wrap = document.getElementById('dbVisualSpreadsheetContainer');
    if (!wrap) return;

    if (tableKey === 'CATALOG') {
        const rows = showroomCatalog.map(item => {
            const inStock = isGarmentInStock(item);
            const units = getTotalGarmentUnits(item);
            return `
                <tr>
                    <td><img src="${item.frontImg}" alt="${item.title}" class="db-row-thumb" /></td>
                    <td><input type="text" id="dbRowSku_${item.id}" class="db-cell-input" style="width:105px;" value="${item.sku || item.id}" /></td>
                    <td><input type="text" id="dbRowBrand_${item.id}" class="db-cell-input" style="width:125px;" value="${item.brand}" /></td>
                    <td><input type="text" id="dbRowTitle_${item.id}" class="db-cell-input" style="width:230px;" value="${item.title}" /></td>
                    <td>
                        <select id="dbRowDept_${item.id}" class="db-cell-select">
                            <option value="EETHMAN" ${item.department === 'EETHMAN' ? 'selected' : ''}>EETHMAN</option>
                            <option value="HOLSTEINER" ${item.department === 'HOLSTEINER' ? 'selected' : ''}>HOLSTEINER</option>
                            <option value="LOUIS_VENTO" ${item.department === 'LOUIS_VENTO' ? 'selected' : ''}>LOUIS_VENTO</option>
                            <option value="KIDS_WOMENS" ${item.department === 'KIDS_WOMENS' ? 'selected' : ''}>KIDS_WOMENS</option>
                        </select>
                    </td>
                    <td><input type="number" id="dbRowPrice_${item.id}" class="db-cell-input" style="width:82px;" value="${item.price}" min="99" /></td>
                    <td><input type="number" id="dbRowMrp_${item.id}" class="db-cell-input" style="width:82px;" value="${item.mrp}" min="99" /></td>
                    <td><strong style="color:#F8FAFC;">${inStock ? units : 0} pcs</strong></td>
                    <td>
                        <button type="button" class="stock-state-btn ${inStock ? 'in-stock-btn active' : 'stock-out-btn active'}" onclick="setWholeGarmentStockState('${item.id}', ${!inStock})">
                            ${inStock ? '✓ IN STOCK' : '✕ STOCK OUT'}
                        </button>
                    </td>
                    <td>
                        <div style="display:flex;gap:6px;">
                            <button type="button" class="admin-mini-btn gold" onclick="saveVisualCatalogRow('${item.id}')">Save</button>
                            <button type="button" class="db-delete-record-btn" onclick="deleteProductFromDatabase('${item.id}')">Delete</button>
                        </div>
                    </td>
                </tr>
            `;
        }).join('');

        wrap.innerHTML = `
            <table class="db-spreadsheet-table">
                <thead>
                    <tr>
                        <th>Photo</th>
                        <th>SKU Code</th>
                        <th>Brand</th>
                        <th>Collection Title</th>
                        <th>Section</th>
                        <th>Price (₹)</th>
                        <th>MRP (₹)</th>
                        <th>Total Units</th>
                        <th>Stock Status</th>
                        <th>Row Actions</th>
                    </tr>
                </thead>
                <tbody>${rows}</tbody>
            </table>
        `;
    } else if (tableKey === 'ORDERS') {
        const rows = savedShowroomOrders.map((ord, idx) => `
            <tr>
                <td><strong style="color:var(--gold-light);">${ord.orderNumber}</strong></td>
                <td>${ord.invoiceDate}</td>
                <td><strong>${ord.customerName}</strong><br/><span style="color:#94A3B8;font-size:11px;">+91 ${ord.customerPhone}</span></td>
                <td>${(ord.items || []).map(i => `${i.title} (${i.size}×${i.qty})`).join(', ')}</td>
                <td><strong style="color:#34D399;">${formatINR(ord.grandTotal)}</strong></td>
                <td>
                    <select class="db-cell-select" onchange="updateAdminOrderStage(${idx}, this.value)">
                        <option value="CONFIRMED" ${ord.status === 'CONFIRMED' ? 'selected' : ''}>1. CONFIRMED</option>
                        <option value="PACKED" ${ord.status === 'PACKED' ? 'selected' : ''}>2. PACKED</option>
                        <option value="SHIPPED" ${ord.status === 'SHIPPED' ? 'selected' : ''}>3. SHIPPED</option>
                        <option value="OUT_FOR_DELIVERY" ${ord.status === 'OUT_FOR_DELIVERY' ? 'selected' : ''}>4. OUT FOR DELIVERY</option>
                        <option value="DELIVERED" ${ord.status === 'DELIVERED' ? 'selected' : ''}>5. DELIVERED</option>
                    </select>
                </td>
                <td>
                    <div style="display:flex;gap:6px;">
                        <button type="button" class="gold-outline-btn" style="padding:5px 10px;font-size:11px;" onclick="openSavedInvoiceModal(${idx})">Invoice</button>
                        <button type="button" class="db-delete-record-btn" onclick="deleteOrderFromDatabase(${idx})">Delete</button>
                    </div>
                </td>
            </tr>
        `).join('');

        wrap.innerHTML = `
            <table class="db-spreadsheet-table">
                <thead>
                    <tr>
                        <th>Order #</th>
                        <th>Invoice Date</th>
                        <th>Customer</th>
                        <th>Purchased Garments</th>
                        <th>Grand Total</th>
                        <th>Fulfillment Status</th>
                        <th>Row Actions</th>
                    </tr>
                </thead>
                <tbody>${rows || '<tr><td colspan="7" style="text-align:center;padding:24px;color:#94A3B8;">No orders in database.</td></tr>'}</tbody>
            </table>
        `;
    } else {
        const rows = registeredUsers.map(u => `
            <tr>
                <td><code style="color:var(--gold-light);">${u.userId}</code></td>
                <td><input type="text" id="dbCustName_${u.userId}" class="db-cell-input" style="width:170px;" value="${u.fullName}" /></td>
                <td><input type="text" id="dbCustPhone_${u.userId}" class="db-cell-input" style="width:120px;" value="${u.phone}" maxlength="10" /></td>
                <td><input type="email" id="dbCustEmail_${u.userId}" class="db-cell-input" style="width:200px;" value="${u.email || ''}" /></td>
                <td>
                    <select id="dbCustRole_${u.userId}" class="db-cell-select">
                        <option value="CUSTOMER" ${u.role !== 'ADMIN' ? 'selected' : ''}>CUSTOMER</option>
                        <option value="ADMIN" ${u.role === 'ADMIN' ? 'selected' : ''}>ADMIN</option>
                    </select>
                </td>
                <td>
                    <div style="display:flex;gap:6px;">
                        <button type="button" class="admin-mini-btn gold" onclick="saveVisualCustomerRow('${u.userId}')">Save</button>
                        <button type="button" class="db-delete-record-btn" onclick="deleteCustomerFromDatabase('${u.userId}')">Delete</button>
                    </div>
                </td>
            </tr>
        `).join('');

        wrap.innerHTML = `
            <table class="db-spreadsheet-table">
                <thead>
                    <tr>
                        <th>Account ID</th>
                        <th>Full Name</th>
                        <th>10-Digit Mobile</th>
                        <th>Email Address</th>
                        <th>Access Role</th>
                        <th>Row Actions</th>
                    </tr>
                </thead>
                <tbody>${rows}</tbody>
            </table>
        `;
    }
}

function saveVisualCatalogRow(productId) {
    const prod = showroomCatalog.find(p => p.id === productId);
    if (!prod) return;
    prod.sku = (document.getElementById(`dbRowSku_${productId}`)?.value || prod.sku).trim();
    prod.brand = (document.getElementById(`dbRowBrand_${productId}`)?.value || prod.brand).trim();
    prod.title = (document.getElementById(`dbRowTitle_${productId}`)?.value || prod.title).trim();
    prod.department = document.getElementById(`dbRowDept_${productId}`)?.value || prod.department;
    prod.price = Math.max(99, Number(document.getElementById(`dbRowPrice_${productId}`)?.value || prod.price));
    prod.mrp = Math.max(prod.price, Number(document.getElementById(`dbRowMrp_${productId}`)?.value || prod.mrp));

    safeStorageSet(STORAGE_KEYS.CATALOG, showroomCatalog);
    applyCatalogFilters();
    refreshAdminStudio();
    showLuxuryToast(`Saved row "${prod.title}" to Catalog Database!`);
}

function saveVisualCustomerRow(userId) {
    const usr = registeredUsers.find(u => u.userId === userId);
    if (!usr) return;
    usr.fullName = (document.getElementById(`dbCustName_${userId}`)?.value || usr.fullName).trim();
    usr.phone = (document.getElementById(`dbCustPhone_${userId}`)?.value || usr.phone).replace(/\D/g, '').slice(-10);
    usr.email = (document.getElementById(`dbCustEmail_${userId}`)?.value || usr.email).trim();
    usr.role = document.getElementById(`dbCustRole_${userId}`)?.value || usr.role;

    safeStorageSet(STORAGE_KEYS.USERS, registeredUsers);
    refreshAdminStudio();
    showLuxuryToast(`Saved customer "${usr.fullName}" to Accounts Database!`);
}

function loadSelectedDatabaseTableIntoEditor() {
    const sel = document.getElementById('dbTableSelector')?.value || 'CATALOG';
    const heading = document.getElementById('dbEditorTableHeading');
    const editor = document.getElementById('dbRawJsonEditor');

    document.querySelectorAll('#dbSubtablePills .db-subtable-pill').forEach(btn => {
        btn.classList.toggle('active', btn.getAttribute('data-dbtable') === sel);
    });

    renderVisualDatabaseSpreadsheet(sel);

    if (!editor) return;

    if (sel === 'CATALOG') {
        if (heading) heading.textContent = `ADVANCED RAW JSON TABLE EDITOR — CATALOG (${showroomCatalog.length} RECORDS)`;
        const lightCatalog = showroomCatalog.map(p => ({
            id: p.id,
            sku: p.sku,
            brand: p.brand,
            title: p.title,
            department: p.department,
            price: p.price,
            mrp: p.mrp,
            fabric: p.fabric,
            gsm: p.gsm,
            fit: p.fit,
            inStock: p.inStock,
            sizes: p.sizes
        }));
        editor.value = JSON.stringify(lightCatalog, null, 2);
    } else if (sel === 'ORDERS') {
        if (heading) heading.textContent = `ADVANCED RAW JSON TABLE EDITOR — ORDERS (${savedShowroomOrders.length} INVOICES)`;
        editor.value = JSON.stringify(savedShowroomOrders, null, 2);
    } else {
        if (heading) heading.textContent = `ADVANCED RAW JSON TABLE EDITOR — CUSTOMERS (${registeredUsers.length} ACCOUNTS)`;
        editor.value = JSON.stringify(registeredUsers, null, 2);
    }
}

function commitRawJsonEditorToDatabase() {
    const sel = document.getElementById('dbTableSelector')?.value || 'CATALOG';
    const editor = document.getElementById('dbRawJsonEditor');
    if (!editor) return;

    try {
        const parsed = JSON.parse(editor.value);
        if (!Array.isArray(parsed)) {
            showLuxuryToast('Database table root must be a JSON Array.');
            return;
        }
        if (sel === 'CATALOG') {
            showroomCatalog = parsed.map((row, idx) => {
                const existing = showroomCatalog.find(p => p.id === row.id) || DEFAULT_SHOWROOM_CATALOG[idx % DEFAULT_SHOWROOM_CATALOG.length];
                return {
                    ...existing,
                    ...row,
                    frontImg: row.frontImg || existing.frontImg,
                    backImg: row.backImg || existing.backImg
                };
            });
            safeStorageSet(STORAGE_KEYS.CATALOG, showroomCatalog);
            applyCatalogFilters();
        } else if (sel === 'ORDERS') {
            savedShowroomOrders = parsed;
            safeStorageSet(STORAGE_KEYS.ORDERS, savedShowroomOrders);
        } else {
            registeredUsers = parsed;
            safeStorageSet(STORAGE_KEYS.USERS, registeredUsers);
        }
        refreshAdminStudio();
        renderPersonalBagDrawer();
        showLuxuryToast(`Committed updated ${sel} table to Showroom Database!`);
    } catch (err) {
        showLuxuryToast('Invalid JSON syntax in editor. Please check commas and quotes.');
    }
}

function exportFullDatabaseJson() {
    const dump = {
        store: 'KIRUTHIS MENS FASHIONS — The Trendy Store, Tirupur',
        gstin: '33JODPK0345L1ZW',
        exportedAt: new Date().toISOString(),
        catalog: showroomCatalog,
        orders: savedShowroomOrders,
        users: registeredUsers
    };
    const blob = new Blob([JSON.stringify(dump, null, 2)], { type: 'application/json;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'Kiruthis_Showroom_Full_Database_2026.json';
    a.click();
    URL.revokeObjectURL(url);
    showLuxuryToast('Downloaded Kiruthis_Showroom_Full_Database_2026.json');
}

function handleImportDatabaseJsonFile(event) {
    const file = event.target?.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const data = JSON.parse(String(e.target?.result || '{}'));
            if (Array.isArray(data.catalog)) {
                showroomCatalog = data.catalog;
                safeStorageSet(STORAGE_KEYS.CATALOG, showroomCatalog);
            }
            if (Array.isArray(data.orders)) {
                savedShowroomOrders = data.orders;
                safeStorageSet(STORAGE_KEYS.ORDERS, savedShowroomOrders);
            }
            if (Array.isArray(data.users)) {
                registeredUsers = data.users;
                safeStorageSet(STORAGE_KEYS.USERS, registeredUsers);
            }
            applyCatalogFilters();
            refreshAdminStudio();
            renderPersonalBagDrawer();
            showLuxuryToast('Database successfully restored from JSON backup!');
        } catch (err) {
            showLuxuryToast('Could not parse JSON backup file.');
        }
    };
    reader.readAsText(file);
}

function resetDatabaseToClientDefaults() {
    showroomCatalog = JSON.parse(JSON.stringify(DEFAULT_SHOWROOM_CATALOG));
    safeStorageSet(STORAGE_KEYS.CATALOG, showroomCatalog);
    applyCatalogFilters();
    refreshAdminStudio();
    showLuxuryToast('Showroom Database reset to the 14 official Client Demo Collections!');
}

function exportAdminInventoryCsv() {
    let csv = 'SKU,Brand,Collection Title,Section,Selling Price,MRP,Status,M,L,XL,XXL\n';
    showroomCatalog.forEach(p => {
        const s = p.sizes || {};
        csv += `"${p.sku}","${p.brand}","${p.title}","${p.department}",${p.price},${p.mrp},"${isGarmentInStock(p) ? 'IN_STOCK' : 'STOCK_OUT'}",${s.M || 0},${s.L || 0},${s.XL || 0},${s.XXL || 0}\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'Kiruthis_Mens_Fashions_Inventory_2026.csv';
    a.click();
    URL.revokeObjectURL(url);
    showLuxuryToast('Downloaded Kiruthis_Mens_Fashions_Inventory_2026.csv');
}

